                "dtype": dtype,
                "obj_ids": obj_ids,
                "job_name": "Change owner",
                "start_time": datetime.datetime.now(),
                "status": "in progress",
            }
            request.session.modified = True
    return JsonResponse({"jobIds": jobIds})
